use crate::pull;
use crate::tally;
use std::fs;
use std::path::Path;

pub fn rib_c() -> i32 {
    let _ = tally::lines();
    let dest = Path::new("/app/blotbay/rows.json");

    // A failed pour must never expose output from an earlier invocation.
    match fs::remove_file(dest) {
        Ok(()) => {}
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => {}
        Err(err) => {
            eprintln!("weltquay: cannot remove stale output: {err}");
            return 1;
        }
    }

    let buf = match fs::read("/app/quaybag/night.bin") {
        Ok(buf) => buf,
        Err(err) => {
            eprintln!("weltquay: cannot read body: {err}");
            return 1;
        }
    };
    let available_bits = match buf.len().checked_mul(8) {
        Some(bits) => bits,
        None => {
            eprintln!("weltquay: body is too large");
            return 1;
        }
    };
    if available_bits < pull::WIDTH_BITS as usize {
        eprintln!(
            "weltquay: short body ({} bits, layout requires {} bits)",
            available_bits,
            pull::WIDTH_BITS
        );
        return 1;
    }

    if let Some(parent) = dest.parent() {
        if let Err(err) = fs::create_dir_all(parent) {
            eprintln!("weltquay: cannot create output directory: {err}");
            return 1;
        }
    }
    let (a, b, c, d, e, f) = pull::dump(&buf);
    let body = format!(
        "{{\"kind\":{},\"lane\":{},\"mode\":{},\"welt\":{},\"tail\":{},\"mark\":{}}}\n",
        a, b, c, d, e, f
    );
    if let Err(err) = fs::write(dest, body) {
        eprintln!("weltquay: cannot write output: {err}");
        let _ = fs::remove_file(dest);
        return 1;
    }
    0
}
EOF
